//! Every case of `policy.jsonl` against `policy::check_overrides_with`,
//! and the header's sweep regenerated by the generator's rule and
//! compared by count and SHA-256.

mod common;

use bettermemory_core::config::ACKNOWLEDGE_NAMES;
use bettermemory_core::policy::{check_overrides_with, PolicyRefusal};
use bettermemory_core::pyvalue::PyValue;
use common::jsonl;
use common::parity::Ledger;
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

fn strings(v: &Value) -> Vec<String> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|s| s.as_str().unwrap().to_owned())
        .collect()
}

fn to_json(v: &PyValue) -> Value {
    match v {
        PyValue::Str(s) => json!(bettermemory_core::unicode::to_string(s).unwrap()),
        PyValue::List(items) => Value::Array(items.iter().map(to_json).collect()),
        PyValue::Dict(items) => {
            let mut map = serde_json::Map::new();
            for (k, v) in items {
                let PyValue::Str(k) = k else {
                    panic!("a str key")
                };
                map.insert(
                    bettermemory_core::unicode::to_string(k).unwrap(),
                    to_json(v),
                );
            }
            Value::Object(map)
        }
        other => panic!("unexpected {other:?}"),
    }
}

fn run(
    tool: &str,
    force: bool,
    ack: &dyn Fn(&str) -> bool,
    ff: bool,
    fa: &[String],
    mk: &[String],
) -> Result<(), PolicyRefusal> {
    check_overrides_with(ff, fa, &|k| mk.iter().any(|m| m == k), tool, force, ack)
}

const FORBID: [&[&str]; 4] = [
    &[],
    &["credential"],
    &["truncation", "credential", "credential"],
    &[
        "credential",
        "transient",
        "scope_mismatch",
        "user_claim",
        "truncation",
        "bogus",
    ],
];
const MANAGED: [&[&str]; 4] = [
    &[],
    &["policy.forbid_force"],
    &["policy.forbid_acknowledge"],
    &[
        "policy.forbid_force",
        "policy.forbid_acknowledge",
        "scopes.allowed",
    ],
];

fn owned(items: &[&str]) -> Vec<String> {
    items.iter().map(|s| (*s).to_owned()).collect()
}

#[test]
fn policy_every_case() {
    let mut lines = jsonl("policy.jsonl");
    let header = lines.remove(0);
    assert_eq!(header["cases"].as_u64(), Some(lines.len() as u64));
    let ledger = Ledger::new("golden_policy", "policy.jsonl");
    let mut failures = Vec::new();
    for (i, case) in lines.iter().enumerate() {
        let ack = case["ack"].as_object().unwrap().clone();
        let got = run(
            case["tool"].as_str().unwrap(),
            case["force"].as_bool().unwrap(),
            &|name| ack.get(name).and_then(Value::as_bool).unwrap_or(false),
            case["ff"].as_bool().unwrap(),
            &strings(&case["fa"]),
            &strings(&case["mk"]),
        );
        let got = match got {
            Ok(()) => Value::Null,
            Err(r) => json!({"msg": r.to_string(), "ev": to_json(&r.event_fields())}),
        };
        if got != case["r"] {
            failures.push(format!("#{i}: native {got}\n reference {}", case["r"]));
        }
    }
    assert!(!lines.is_empty());
    ledger.settle(lines.len(), &failures);
}

#[test]
fn policy_sweep_digest() {
    let header = jsonl("policy.jsonl").remove(0);
    let mut out: Vec<String> = Vec::new();
    for tool in ["memory_write", "memory_update"] {
        for force in [false, true] {
            for bits in 0..32u32 {
                let ack = |name: &str| {
                    ACKNOWLEDGE_NAMES
                        .iter()
                        .position(|n| *n == name)
                        .is_some_and(|i| bits >> i & 1 == 1)
                };
                for ff in [false, true] {
                    for fa in FORBID {
                        for mk in MANAGED {
                            out.push(match run(tool, force, &ack, ff, &owned(fa), &owned(mk)) {
                                Ok(()) => "-".to_owned(),
                                Err(r) => [
                                    r.to_string(),
                                    r.flags.join(","),
                                    r.keys.join(","),
                                    r.managed.join(","),
                                ]
                                .join("\t"),
                            });
                        }
                    }
                }
            }
        }
    }
    let digest = Sha256::digest(out.join("\n").as_bytes());
    let hex: String = digest.iter().map(|b| format!("{b:02x}")).collect();
    assert_eq!(header["sweep"]["count"].as_u64(), Some(out.len() as u64));
    assert_eq!(header["sweep"]["sha256"].as_str(), Some(hex.as_str()));
}
